import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Heizöl to MQTT","text":"Prix du fioul domestique pour Home Assistant","tagline":"Interroge les calculateurs de prix publics d'Esyoil et de Heizöl24, puis publie les meilleurs tarifs ainsi que les offres individuelles des fournisseurs via la découverte MQTT.","actions":[{"theme":"brand","text":"Installation","link":"/fr/projects/heizoel-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/heizoel-to-mqtt"}]},"features":[{"icon":"🛢️","title":"Prix du fioul domestique","details":"Récupère les meilleurs prix pour un code postal, une quantité et des options de livraison configurés."},{"icon":"📍","title":"Allemagne et Autriche","details":"Consultation des prix pour des codes postaux en Allemagne et en Autriche."},{"icon":"🧾","title":"Offres des fournisseurs","details":"Jusqu'à six offres de fournisseurs par source et par quantité, incluant le prix au litre, le prix pour 100 litres et le prix total."},{"icon":"🔎","title":"Esyoil et Heizöl24","details":"Les points de terminaison (endpoints) des calculateurs de prix publics sont interrogés et normalisés."},{"icon":"🏠","title":"Découverte MQTT (MQTT Discovery)","details":"Home Assistant crée automatiquement des entités pour les prix, les fournisseurs et l'état."},{"icon":"🧰","title":"Diagnostics","details":"Journalisation (logs) facultative des fournisseurs, avec masquage des données, pour les tests et le dépannage."}]},"headers":[],"relativePath":"fr/projects/heizoel-to-mqtt/index.md","filePath":"fr/projects/heizoel-to-mqtt/index.md","lastUpdated":1793127012000}`),r={name:"fr/projects/heizoel-to-mqtt/index.md"};function o(l,e,n,u,p,d){return i(),s("div",null,[...e[0]||(e[0]=[a('<p><a id="index"></a><a id="statut"></a></p><h2 id="uberblick" tabindex="-1">Aperçu <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Aperçu {#uberblick}&quot;">​</a></h2><p>« Heizöl to MQTT » (Fioul domestique vers MQTT) est une application pour Home Assistant qui fournit les prix du fioul domestique dans Home Assistant via la découverte MQTT (MQTT Discovery).</p><p>L&#39;application interroge les points de terminaison des calculateurs de prix publics et normalise les meilleures offres pour chaque source et chaque quantité (en litres). Elle est destinée exclusivement à l&#39;Allemagne et à l&#39;Autriche.</p><div class="info custom-block"><p class="custom-block-title">Origine</p><p>Cette implémentation est adaptée et inspirée de l&#39;adaptateur ioBroker <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a>.</p></div><h2 id="status" tabindex="-1">État <a class="header-anchor" href="#status" aria-label="Permalink to &quot;État {#status}&quot;">​</a></h2><p>L&#39;application peut être testée au sein de Home Assistant et fournit des valeurs via la découverte MQTT. Elle prend en charge des entités « meilleur prix » ainsi qu&#39;un maximum de six offres de fournisseurs par source et par quantité.</p><p>Les points de terminaison de prix utilisés correspondent à ceux de sites web publics, et non à des API stables et officiellement documentées.</p><h2 id="weitere-seiten" tabindex="-1">Autres pages <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Autres pages {#weitere-seiten}&quot;">​</a></h2><ul><li><a href="/fr/projects/heizoel-to-mqtt/installation">Installation</a></li><li><a href="/fr/projects/heizoel-to-mqtt/configuration">Configuration</a></li><li><a href="/fr/projects/heizoel-to-mqtt/entities">Entités</a></li><li><a href="/fr/projects/heizoel-to-mqtt/examples">Exemples</a></li></ul>',10)])])}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
